INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Dissolution clause requirement
(3, 'Tax-Exempt Organizations', 'What must a Section 501(c)(3) organization''s governing documents include regarding dissolution of the entity?', '["A provision naming the founder''s heirs as beneficiaries of remaining assets", "A clause providing that assets will be distributed to another exempt organization or the government upon dissolution", "A requirement that the organization must operate for at least 25 years before dissolving", "A statement that all assets revert to the state treasury upon dissolution"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the organizational test requires a dissolution clause directing that remaining assets go to another exempt organization or to the government. Option A fails because assets cannot inure to private individuals — this would violate the private inurement prohibition. Option D imposes a specific government-only requirement not found in the statute, which also permits distribution to other exempt organizations.', 'easy', 1),

-- Q2: medium / L2 — Controlled entity payments as UBIT
(3, 'Tax-Exempt Organizations', 'Heritage Education Foundation, a 501(c)(3) university, owns 90% of a for-profit tutoring company. The tutoring company pays the university $200,000 in annual rent for classroom space. How is this rental income treated for UBIT purposes?', '["Excluded entirely because all rental income from real property is exempt from UBIT", "Excluded because the rental income supports the university''s exempt educational purpose", "Treated as UBIT to the extent the rent exceeds fair market value, since the tutoring company is a controlled entity", "Fully included in UBIT because all payments from for-profit subsidiaries are automatically taxable"]'::jsonb, 2, 'Under IRC Section 512(b)(13), rent received from a controlled entity (80%+ ownership) is included in UBIT to the extent it exceeds fair market value. The general real property rent exclusion under Section 512(b)(3) is modified for controlled entities. Option A ignores the controlled-entity modification. Option D overstates the rule — only the excess over FMV is taxable, not the entire payment.', 'medium', 2),

-- Q3: medium / L3 — Personal property rents 10% de minimis rule
(3, 'Tax-Exempt Organizations', 'Lakewood Community Center, a 501(c)(3), leases a building to a commercial tenant. The lease also includes office furniture and equipment. Total annual rent is $100,000, with $8,000 allocated to personal property. How is the rental income treated for UBIT purposes?', '["The entire $100,000 is excluded from UBIT because the personal property rent is incidental, representing less than 10% of total rents under the lease", "Only the $8,000 personal property portion is included in UBIT while the $92,000 real property rent is excluded", "The entire $100,000 is subject to UBIT because the lease includes any personal property", "The $92,000 real property portion is excluded, but the $8,000 triggers UBIT on the full $100,000"]'::jsonb, 0, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT. Rents from personal property are also excluded when incidental — meaning less than 10% of total rents under the lease. Here, $8,000/$100,000 = 8%, which is below the 10% threshold, so the entire $100,000 is excluded. Option B incorrectly treats the personal property portion as taxable despite being within the de minimis threshold.', 'medium', 3),

-- Q4: medium / L3 — Section 501(h) expenditure election
(3, 'Tax-Exempt Organizations', 'River Valley Alliance, a 501(c)(3) public charity, spends 18% of its total expenditures on lobbying activities. Its board considers making the Section 501(h) expenditure election. What advantage does the 501(h) election provide compared to the default substantial-part test?', '["The election eliminates all restrictions on lobbying, allowing unlimited lobbying expenditures", "The election converts the lobbying limitation from a dollar amount to a facts-and-circumstances test", "The election allows the organization to engage in political campaign activity in addition to lobbying", "The election replaces the vague substantial-part test with specific dollar thresholds based on exempt-purpose expenditures"]'::jsonb, 3, 'Under IRC Section 501(h), eligible public charities may elect the expenditure test, which replaces the subjective "substantial part" test with measurable dollar thresholds tied to exempt-purpose expenditures. This provides a clear safe harbor with defined limits. Option A is wrong because the election still imposes lobbying limits. Option C is wrong because the absolute prohibition on political campaign activity is entirely unaffected by the 501(h) election.', 'medium', 3),

-- Q5: medium / L2 — Form 990-EZ filing thresholds
(3, 'Tax-Exempt Organizations', 'Neighborhood Watch Alliance, a 501(c)(3), has gross receipts of $180,000 and total assets of $450,000 for the 2025 tax year. Which annual information return must it file?', '["Form 990 because gross receipts exceed $50,000", "Form 990-EZ because gross receipts are under $200,000 and total assets are under $500,000", "Form 990-N (e-Postcard) because gross receipts are below $200,000", "No return is required because the organization is a small public charity"]'::jsonb, 1, 'Under IRC Section 6033, a 501(c)(3) organization with gross receipts under $200,000 AND total assets under $500,000 may file the simplified Form 990-EZ. Both thresholds are met ($180,000 < $200,000 and $450,000 < $500,000). Option A is incorrect because the full Form 990 is required only when gross receipts reach $200,000 or total assets reach $500,000. Option C is wrong because Form 990-N is limited to organizations with gross receipts of $50,000 or less.', 'medium', 2),

-- Q6: hard / L4 — Supporting organization 509(a)(3) reclassification
(3, 'Tax-Exempt Organizations', 'Greenfield Community Trust raises all its funds from a single wealthy family and distributes grants exclusively to Greenfield Hospital, a 501(c)(3) public charity. The trust is classified as a Section 509(a)(3) supporting organization. Greenfield Hospital severs its relationship with the trust. Evaluate the trust''s tax classification after the relationship ends and the primary consequence it faces.', '["The trust retains its public charity classification because its historical relationship with the hospital is sufficient", "The trust automatically becomes a Section 509(a)(1) public charity based on its grant-making activities", "The trust is reclassified as a private foundation because it no longer meets the 509(a)(3) requirement of supporting a public charity, subjecting it to Sections 4940-4945 excise taxes", "The trust loses its tax-exempt status entirely because it cannot operate without a supported organization"]'::jsonb, 2, 'Under IRC Section 509(a)(3), a supporting organization must be operated exclusively to support one or more public charities. When the supported relationship terminates, the organization reverts to the default presumption under Section 509(a) — private foundation status — triggering excise taxes under Sections 4940–4945. Option A is wrong because 509(a)(3) requires an ongoing operational relationship, not merely historical ties. Option D overstates the consequence; the trust retains 501(c)(3) status but as a private foundation.', 'hard', 4),

-- Q7: medium / L2 — Convenience exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'State University, a 501(c)(3), operates an on-campus laundry facility used exclusively by students living in dormitories. The laundry generates $45,000 in annual revenue. Is this income subject to UBIT?', '["No, because the laundry is operated for the convenience of students, which is a statutory exclusion from UBIT", "Yes, because operating a laundry is a trade or business unrelated to education", "No, because any activity conducted on campus is automatically related to the university''s exempt purpose", "Yes, because the $45,000 exceeds the $1,000 specific deduction threshold"]'::jsonb, 0, 'Under IRC Section 513(a)(2), activities conducted primarily for the convenience of members, students, patients, or employees are excluded from UBIT regardless of whether they meet the three-part test. An on-campus laundry serving dormitory students qualifies for this convenience exclusion. Option B ignores the statutory exclusion. Option D confuses the $1,000 specific deduction (which reduces taxable UBI) with a threshold for determining whether an activity is subject to UBIT.', 'medium', 2),

-- Q8: easy / L1 — Form 990 filing deadline
(3, 'Tax-Exempt Organizations', 'What is the filing deadline for Form 990 for a calendar-year tax-exempt organization?', '["March 15 of the following year", "April 15 of the following year", "June 15 of the following year", "May 15 of the following year"]'::jsonb, 3, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the end of the tax year. For calendar-year organizations, this is May 15. Option B (April 15) is the deadline for individual income tax returns, a common point of confusion. Option A (March 15) is the filing deadline for S corporation and partnership returns, not exempt organizations.', 'easy', 1),

-- Q9: easy / L1 — Form 990-N (e-Postcard) threshold
(3, 'Tax-Exempt Organizations', 'Which tax-exempt organizations are eligible to file Form 990-N (e-Postcard)?', '["Organizations with gross receipts under $200,000", "All private foundations regardless of size", "Organizations with gross receipts normally $50,000 or less", "Organizations with total assets under $500,000"]'::jsonb, 2, 'Under IRC Section 6033, the Form 990-N (e-Postcard) is available to tax-exempt organizations with gross receipts normally $50,000 or less. It requires only basic information: name, address, EIN, and confirmation of continued eligibility. Option A describes the upper bound for Form 990-EZ, not the e-Postcard. Option B is incorrect because private foundations must file Form 990-PF regardless of size.', 'easy', 1),

-- Q10: medium / L2 — Research exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Coastal Research Institute, a 501(c)(3), conducts contract research for the U.S. Department of Defense on marine biology topics. The institute receives $350,000 from the contract. Is this research income subject to UBIT?', '["Yes, because contract research performed for a specific client is a trade or business regularly carried on", "No, because research performed for the United States government is a statutory exclusion from UBIT", "Yes, because the $350,000 greatly exceeds the $1,000 specific deduction threshold", "No, because all income earned by a scientific organization is automatically exempt from UBIT"]'::jsonb, 1, 'Under IRC Section 512(b)(7)–(9), research performed for the United States or any of its agencies is specifically excluded from UBIT, regardless of whether it meets the three-part test. Option A incorrectly applies the general UBIT test without considering the statutory research exclusion. Option D overstates the exemption — not all income earned by scientific organizations is exempt, only qualifying research activities.', 'medium', 2),

-- Q11: medium / L2 — Late filing penalties for Form 990
(3, 'Tax-Exempt Organizations', 'Riverside Youth Center, a 501(c)(3) with gross receipts of $400,000, files its Form 990 sixty days late without obtaining a valid extension. What penalty applies under IRC Section 6652(c)?', '["$20 per day for each day the return is late, up to the lesser of $10,500 or 5% of gross receipts", "A flat penalty of $500 for any late filing regardless of duration", "$100 per day with no maximum cap for organizations of any size", "No penalty applies because the organization is tax-exempt"]'::jsonb, 0, 'Under IRC Section 6652(c)(1)(A), the penalty for late filing of Form 990 is $20 per day (up to the lesser of $10,500 or 5% of gross receipts) for organizations with gross receipts under $1,186,000. Riverside''s 60-day delay results in a $1,200 penalty ($20 x 60 days). Option B incorrectly states a flat penalty not found in the statute. Option D is wrong because tax-exempt status does not eliminate information return filing penalties.', 'medium', 2),

-- Q12: medium / L2 — Churches/hospitals automatic public charity classification
(3, 'Tax-Exempt Organizations', 'Mercy General Hospital, a 501(c)(3), receives 95% of its revenue from patient fees and only 5% from government grants and public donations. How is Mercy General classified for purposes of distinguishing public charities from private foundations?', '["Private foundation, because it does not meet the one-third public support test", "Private foundation, because patient fee revenue is not considered public support", "Public charity under Section 509(a)(2), because it receives more than one-third from exempt function gross receipts", "Public charity, because hospitals are automatically classified as public charities regardless of funding sources"]'::jsonb, 3, 'Under IRC Section 509(a)(1), hospitals are among the organizations — alongside churches and schools — automatically classified as public charities regardless of their funding mix. Mercy General need not satisfy the one-third support or gross receipts tests. Option A incorrectly applies the support test to an organization type that is exempt from it by statute. Option C reaches a similar conclusion but by the wrong reasoning — the automatic classification controls.', 'medium', 2),

-- Q13: easy / L1 — Private inurement prohibition definition
(3, 'Tax-Exempt Organizations', 'What does the private inurement prohibition under Section 501(c)(3) prevent?', '["Net earnings of the organization from benefiting any private shareholder or individual", "Tax-exempt organizations from earning any profit whatsoever", "The organization from paying reasonable salaries to its employees", "Tax-exempt organizations from investing in publicly traded securities"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the private inurement prohibition prevents any part of the organization''s net earnings from inuring to the benefit of private shareholders or individuals (insiders). Option B is incorrect because tax-exempt organizations may generate surplus revenue — they simply cannot distribute it to insiders. Option C is wrong because reasonable compensation for services rendered is explicitly permitted.', 'easy', 1),

-- Q14: medium / L3 — One-third support test application (509(a)(1))
(3, 'Tax-Exempt Organizations', 'New Horizons Education Fund, a 501(c)(3), receives the following support over the relevant testing period: $300,000 from government grants, $100,000 from public contributions, and $900,000 from a single donor family. Applying the one-third support test under Section 509(a)(1), how is New Horizons classified?', '["Public charity, because total support from all sources exceeds $1,000,000", "Public charity, because the $300,000 in government grants alone exceeds the required threshold", "Private foundation, because public and government support ($400,000) is less than one-third of total support ($1,300,000)", "Private foundation, because receiving any support from a single family is automatically disqualifying"]'::jsonb, 2, 'Under IRC Section 509(a)(1), an organization must normally receive at least one-third of its total support from government and public sources to qualify as a public charity. Total support is $1,300,000, and qualifying public/government support is $400,000 (30.8%), which falls below the one-third threshold (33.3%). Option D is incorrect because receiving support from a single family is not per se disqualifying — the issue is the proportion of total support from public sources. Option A confuses total revenue with the support ratio.', 'medium', 3),

-- Q15: easy / L1 — Form 990-PF for all private foundations
(3, 'Tax-Exempt Organizations', 'Which information return must all private foundations file annually, regardless of their size?', '["Form 990-N (e-Postcard)", "Form 990-PF", "Form 990-EZ", "Form 1065"]'::jsonb, 1, 'Under IRC Section 6033, all private foundations must file Form 990-PF annually regardless of gross receipts or total assets. This form includes detailed financial statements and excise tax computations under Sections 4940–4945. Option A (e-Postcard) is only for small organizations with gross receipts of $50,000 or less, and private foundations are ineligible. Option D (Form 1065) is the partnership return, not applicable to foundations.', 'easy', 1),

-- Q16: easy / L1 — $1,000 specific deduction for UBIT
(3, 'Tax-Exempt Organizations', 'What specific deduction is available to reduce unrelated business taxable income under Section 512?', '["A 20% qualified business income deduction under Section 199A", "An unlimited charitable contribution deduction for exempt organizations", "A standard deduction of $12,950 for all tax-exempt filers", "A $1,000 specific deduction under IRC Section 512(b)(12)"]'::jsonb, 3, 'Under IRC Section 512(b)(12), tax-exempt organizations may claim a $1,000 specific deduction against unrelated business taxable income, effectively exempting the first $1,000 of UBI from tax. Option A is incorrect because the Section 199A deduction applies to qualified business income of individuals and pass-through entities, not tax-exempt organizations. Option C fabricates a standard deduction that does not exist for exempt organizations.', 'easy', 1),

-- Q17: medium / L2 — Schedule J compensation disclosure
(3, 'Tax-Exempt Organizations', 'Eastside Community Foundation files Form 990 annually. Its CEO earns $500,000 per year. Which Form 990 schedule requires the foundation to report detailed compensation information for its officers and key employees?', '["Schedule J — Compensation Information", "Schedule A — Public Charity Status and Public Support", "Schedule B — Schedule of Contributors", "Schedule D — Supplemental Financial Statements"]'::jsonb, 0, 'Schedule J of Form 990 requires reporting of compensation information for officers, directors, trustees, key employees, and highest-compensated employees, capturing total compensation, benefits, and bonuses. Option B (Schedule A) relates to public charity status and support calculations, not compensation. Option C (Schedule B) reports contributor information and is the only Form 990 schedule that is not publicly available.', 'medium', 2),

-- Q18: hard / L4 — Second-tier 200% excise tax under Section 4958
(3, 'Tax-Exempt Organizations', 'Dr. Reeves, the chief medical officer of a 501(c)(3) health system, receives total compensation of $3,200,000. An IRS examination determines reasonable compensation is $1,200,000, creating a $2,000,000 excess benefit. Dr. Reeves pays the initial 25% excise tax but fails to correct the excess benefit within the taxable period. Evaluate the total excise tax consequences to Dr. Reeves under Section 4958.', '["Only the initial 25% tax ($500,000) applies because the IRS cannot impose additional penalties after the initial assessment", "The total tax liability is $4,500,000: the initial 25% tax ($500,000) plus an additional 200% tax ($4,000,000) for failure to correct within the taxable period", "The total tax liability is $1,000,000: a flat 50% tax on the excess benefit with no additional tier", "The IRS revokes the organization''s tax-exempt status instead of imposing any additional excise taxes on Dr. Reeves"]'::jsonb, 1, 'Under IRC Section 4958, the initial excise tax on a disqualified person is 25% of the excess benefit ($500,000). If the excess benefit is not corrected within the taxable period, an additional 200% tax ($4,000,000) is imposed, totaling $4,500,000. Option A incorrectly assumes no second-tier tax exists. Option D confuses intermediate sanctions — which were designed as an alternative to revocation — with revocation itself; both remedies can apply in extreme cases but the question addresses excise tax consequences.', 'hard', 4),

-- Q19: hard / L4 — Private foundation lobbying as taxable expenditure (Section 4945)
(3, 'Tax-Exempt Organizations', 'Clarke Family Foundation, a private foundation, spends $150,000 lobbying Congress for education reform legislation. The foundation''s program director approved the expenditure believing it furthered the educational mission. Analyze the excise tax consequences under Section 4945 for both the foundation and the program director.', '["No excise tax applies because lobbying for education reform is related to the foundation''s exempt educational purpose", "A 10% tax on the foundation and no tax on the program director because self-dealing rules apply instead", "A 20% tax ($30,000) on the foundation, and a 5% tax ($7,500) on the program director for knowingly approving the taxable expenditure", "The foundation loses its tax-exempt status immediately with no excise tax imposed"]'::jsonb, 2, 'Under IRC Section 4945(a), lobbying expenditures by private foundations are classified as taxable expenditures regardless of their connection to exempt purposes. The initial tax is 20% on the foundation ($30,000) and 5% on any foundation manager who knowingly approved the expenditure ($7,500, subject to a $10,000 cap per expenditure). Option A incorrectly assumes that a relationship to exempt purposes excuses the prohibition. Option B confuses the tax rates — 10%/5% are the self-dealing rates under Section 4941, not the taxable expenditure rates under Section 4945.', 'hard', 4),

-- Q20: easy / L1 — Bingo games exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Under Section 513, which recreational activity is specifically excluded from unrelated business income tax?', '["Casino-style gambling operated for fundraising purposes", "Paid admission to professional sporting events hosted by the organization", "Online gaming tournaments with entry fees and cash prizes", "Bingo games in jurisdictions where commercial bingo is not ordinarily conducted"]'::jsonb, 3, 'Under IRC Section 513(f), income from bingo games is excluded from UBIT provided the games are legal and commercial bingo is not ordinarily carried out in the jurisdiction. This is a narrow statutory exclusion. Option A is incorrect because casino-style gambling does not receive a specific UBIT exclusion under Section 513. Option B describes an activity that would likely constitute unrelated trade or business subject to UBIT.', 'easy', 1),

-- Q21: medium / L3 — Private inurement vs private benefit distinction
(3, 'Tax-Exempt Organizations', 'Hilltop Arts Center, a 501(c)(3), hires a renowned local architect — who has no relationship with the board or any officer — to design a new gallery wing at a fee 50% above market rate. No insider benefits from the arrangement. Which IRS doctrine applies to this transaction?', '["The private benefit doctrine, because an unrelated individual receives excessive benefit even though no insider is involved", "The private inurement prohibition, because any overpayment to a contractor constitutes inurement", "The self-dealing rules under Section 4941, because the architect is a disqualified person", "No doctrine applies because fair-market-value comparisons are irrelevant for 501(c)(3) organizations"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the private benefit doctrine prohibits conferring excessive benefits on any person — insider or not. The private inurement prohibition (Option B) applies only to insiders with a personal and private interest in the organization. Since the architect has no insider relationship, private benefit — not inurement — is the correct framework. Option C is wrong because Section 4941 applies to private foundations and disqualified persons, not unrelated third-party contractors.', 'medium', 3),

-- Q22: medium / L3 — Organization manager tax under Section 4941
(3, 'Tax-Exempt Organizations', 'Brooks Family Foundation, a private foundation, purchases office supplies at fair market value from a company owned by the founder''s son. The foundation''s executive director reviews and approves the purchase, knowing the vendor is a disqualified person. What excise tax liability does the executive director face under Section 4941?', '["No liability, because the transaction was conducted at fair market value", "5% of the amount involved for knowingly participating in an act of self-dealing", "10% of the amount involved as the primary self-dealer in the transaction", "25% of the amount involved under the intermediate sanctions rules"]'::jsonb, 1, 'Under IRC Section 4941(a)(2), a foundation manager who knowingly participates in an act of self-dealing faces a 5% excise tax on the amount involved. The 10% initial tax (Option C) applies to the disqualified person — the self-dealer — not the manager. Option A is incorrect because self-dealing under Section 4941 is based on the nature of the transaction; even fair-market-value sales between a foundation and a disqualified person are prohibited. Option D applies Section 4958 intermediate sanctions, which govern public charities, not private foundations.', 'medium', 3),

-- Q23: medium / L2 — Operational test requirements
(3, 'Tax-Exempt Organizations', 'Sunrise Arts Collective, a 501(c)(3), devotes 60% of its activities to producing community theater and 40% to renting event space to private parties for profit. The rental income funds the theater program. Does the Collective satisfy the operational test?', '["Yes, because the rental income is used to fund exempt activities", "Yes, because the organization devotes more than half its activities to exempt purposes", "Potentially no, because dedicating 40% of activities to a non-exempt commercial enterprise may indicate the organization is not operated primarily for exempt purposes", "No, because any commercial activity automatically disqualifies a 501(c)(3) organization"]'::jsonb, 2, 'Under IRC Section 501(c)(3), the operational test requires an organization to be operated primarily for exempt purposes. A 40% commitment to non-exempt commercial activity raises substantial questions about compliance. The fact that profits fund exempt activities (Option A) does not make the activity itself related to exempt purposes — the operational test examines what the organization does, not how it uses revenue. Option D overstates the rule; incidental commercial activity does not disqualify an organization.', 'medium', 2),

-- Q24: hard / L4 — Gross receipts test 509(a)(2) vs one-third support test 509(a)(1)
(3, 'Tax-Exempt Organizations', 'Metro Community Arts, a 501(c)(3), receives $200,000 from ticket sales at exempt-function performances, $80,000 from membership fees, $50,000 from government grants, and $70,000 from investment income. The organization does not qualify under the one-third support test of Section 509(a)(1). Evaluate whether Metro qualifies as a public charity under Section 509(a)(2) and identify the critical distinction between the two tests.', '["Metro does not qualify under 509(a)(2) because investment income disqualifies any organization from public charity status", "Metro qualifies under 509(a)(2) because its total revenue exceeds $400,000, which automatically satisfies the gross receipts test", "Metro does not qualify under either test because ticket sales revenue is never considered public support", "Metro qualifies under 509(a)(2) because contributions, membership fees, and exempt-function gross receipts ($330,000) exceed one-third of total support ($400,000), and 509(a)(2) counts exempt-function revenue that 509(a)(1) does not"]'::jsonb, 3, 'Under IRC Section 509(a)(2), an organization qualifies as a public charity if it normally receives more than one-third of support from contributions, membership fees, and gross receipts from exempt-function activities. Metro''s qualifying support is $330,000 out of $400,000 total (82.5%), far exceeding one-third. The critical distinction is that 509(a)(2) counts exempt-function gross receipts (like ticket sales), while 509(a)(1) does not. Option A is wrong because investment income is included in total support but its presence does not disqualify the organization. Option C incorrectly states that ticket sales are never considered support.', 'hard', 4),

-- Q25: hard / L4 — Combined ownership analysis under Section 4943
(3, 'Tax-Exempt Organizations', 'Patel Family Foundation, a private foundation, owns 12% of voting stock in TechVentures Corp. The Patel family members (all disqualified persons) personally own an additional 15%. The foundation''s attorney advises that no excess business holdings problem exists because neither the foundation nor the family individually exceeds 20%. Evaluate whether the attorney''s analysis is correct under Section 4943.', '["The attorney is incorrect; Section 4943 tests combined holdings of the foundation and all disqualified persons, and the 27% combined total exceeds the 20% permitted holding, creating excess holdings subject to a 10% excise tax", "The attorney is correct; Section 4943 tests the foundation''s holdings and disqualified persons'' holdings separately against the 20% limit", "The attorney is incorrect, but only because the foundation alone exceeds a 10% limit that applies when disqualified persons also hold stock", "The attorney is correct; the excess business holdings rules apply only when the foundation itself holds more than 50% of voting stock"]'::jsonb, 0, 'Under IRC Section 4943, the combined holdings of a private foundation and all disqualified persons cannot exceed 20% of the voting stock of any business enterprise. The foundation (12%) and the Patel family (15%) together hold 27%, exceeding the 20% limit by 7% and triggering a 10% initial excise tax on the excess holdings. Option B incorrectly separates the analysis — Section 4943 explicitly aggregates foundation and disqualified person holdings. Option D applies a threshold that does not exist in the statute.', 'hard', 4),

-- Q26: hard / L3 — Debt-financed income ratio calculation under Section 514
(3, 'Tax-Exempt Organizations', 'Maple Street Charities, a 501(c)(3), purchased a rental property for $800,000, financing $600,000 with a mortgage. The property generates $120,000 in annual rental income and has an average adjusted basis of $750,000. Applying the debt-financed income rules under Section 514, how much of the rental income is subject to UBIT?', '["$120,000, because all rental income from debt-financed property is fully taxable", "$96,000, because the debt-to-basis ratio ($600,000/$750,000 = 80%) is applied to the rental income", "$90,000, because the debt-to-original-cost ratio ($600,000/$800,000 = 75%) is applied to the rental income", "$60,000, because only the portion of income equal to the mortgage balance less equity is taxable"]'::jsonb, 1, 'Under IRC Section 514, debt-financed income is subject to UBIT in proportion to the average acquisition indebtedness divided by the average adjusted basis of the property. Here, $600,000/$750,000 = 80%, so 80% of $120,000 = $96,000 is subject to UBIT. Option A incorrectly treats all debt-financed rental income as fully taxable without applying the ratio. Option C uses the original purchase price ($800,000) rather than the average adjusted basis ($750,000), which is the correct denominator under Section 514.', 'hard', 3),

-- Q27: easy / L2 — Form 8868 extension for Form 990
(3, 'Tax-Exempt Organizations', 'Valley Food Bank, a 501(c)(3), will not be able to file its Form 990 by the May 15 deadline. What form should it file to request additional time?', '["Form 4868 — Application for Automatic Extension for Individual Returns", "Form 7004 — Application for Automatic Extension for Business Returns", "Form 8868 — Application for Automatic Extension for Exempt Organization Returns", "Form 2350 — Application for Extension of Time to File U.S. Income Tax Return Abroad"]'::jsonb, 2, 'Under IRC Section 6081, tax-exempt organizations request an automatic six-month extension using Form 8868. Option A (Form 4868) is the extension form for individual income tax returns, not exempt organizations. Option B (Form 7004) is for business entity returns such as corporations and partnerships. Each form type applies to a specific category of filer.', 'easy', 2),

-- Q28: easy / L1 — Schedule B confidentiality
(3, 'Tax-Exempt Organizations', 'Which Form 990 schedule is specifically exempt from public disclosure requirements?', '["Schedule A — Public Charity Status and Public Support", "Schedule J — Compensation Information", "Schedule O — Supplemental Information", "Schedule B — Schedule of Contributors"]'::jsonb, 3, 'Schedule B of Form 990 lists the organization''s significant contributors and is specifically exempt from public disclosure requirements to protect donor privacy. All other Form 990 schedules — including Schedule A (public charity status), Schedule J (compensation), and Schedule O (supplemental information) — are publicly available upon request. Option B is a common misconception, but officer and key employee compensation data on Schedule J is publicly disclosed.', 'easy', 1),

-- Q29: medium / L3 — Section 4945 expenditure responsibility for grants to non-charities
(3, 'Tax-Exempt Organizations', 'Harper Foundation, a private foundation, awards a $200,000 grant to a 501(c)(4) social welfare organization for community health programs. The foundation does not exercise expenditure responsibility over the grant. What is the consequence under Section 4945?', '["The grant is treated as a taxable expenditure because private foundations must exercise expenditure responsibility when granting to non-501(c)(3) organizations", "No consequence, because grants to any tax-exempt organization are automatically permitted without restriction", "The grant is treated as a taxable expenditure only if the 501(c)(4) uses the funds for lobbying activities", "The foundation must simply report the grant on Form 990-PF with no excise tax consequences"]'::jsonb, 0, 'Under IRC Section 4945(d)(4), grants by private foundations to organizations other than public charities — including 501(c)(4) organizations — are taxable expenditures unless the foundation exercises expenditure responsibility, requiring the grantee to use funds for specified charitable purposes and provide detailed reporting. Option B is incorrect because only grants to public charities are automatically exempt from this requirement. Option C wrongly conditions the consequence on how the grantee uses funds rather than on the foundation''s failure to exercise expenditure responsibility.', 'medium', 3),

-- Q30: medium / L3 — Private foundation presumption under Section 509
(3, 'Tax-Exempt Organizations', 'Clean Water Initiative, a newly formed 501(c)(3), receives its determination letter from the IRS but has not yet applied for public charity classification. Under Section 509, how is the organization initially classified?', '["Public charity, because all newly formed 501(c)(3) organizations start as public charities by default", "Private foundation, because all 501(c)(3) organizations are presumed to be private foundations unless they demonstrate public charity status", "Neither classification applies until the organization files its first Form 990 and establishes a support history", "The IRS assigns classification at random and reviews it after three years of operations"]'::jsonb, 1, 'Under IRC Section 509(a), every 501(c)(3) organization is presumed to be a private foundation unless it affirmatively demonstrates qualification as a public charity under Sections 509(a)(1) through (4). Option A reverses the statutory presumption — the default is private foundation, not public charity. Option C is incorrect because the classification applies immediately upon receiving exempt status; the organization does not exist in a classification vacuum pending its first filing.', 'medium', 3)
;

COMMIT;
